package example.shipping;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
@Configuration(proxyBeanMethods = false)
class DispatchConfiguration {
  @Bean @Profile("regulated")
  DispatchPolicy regulatedPolicy() { return new DispatchPolicy("regulated"); }
  @Bean @Profile("!regulated")
  DispatchPolicy standardPolicy() { return new DispatchPolicy("standard"); }
}
record DispatchPolicy(String mode) {}

