package example.shipping;
import static org.assertj.core.api.Assertions.assertThat;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
@SpringBootTest(classes = ShippingApplication.class, webEnvironment = SpringBootTest.WebEnvironment.NONE)
@ActiveProfiles("regulated")
class DispatchPolicyTest {
  @Autowired DispatchPolicy policy;
  @Test void regulatedPolicyIsSelected() {
    assertThat(policy.mode()).isEqualTo("regulated");
  }
}

